import crypto from 'crypto';
const SHORT={8:'\\b',9:'\\t',10:'\\n',12:'\\f',13:'\\r',34:'\\"',92:'\\\\'};
function esc(s){let o='';for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);if(SHORT[c]!==undefined)o+=SHORT[c];else if(c>=0x20&&c<=0x7e)o+=s[i];else o+='\\u'+c.toString(16).padStart(4,'0');}return o;}
const b64u=b=>Buffer.from(b).toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const [,,payload,secret]=process.argv;
const hdr='{"alg":"HS256","typ":"JWT"}';
const pl='{"data":"'+esc(payload)+'"}';
const si=b64u(Buffer.from(hdr,'utf8'))+'.'+b64u(Buffer.from(pl,'utf8'));
const sig=b64u(crypto.createHmac('sha256',Buffer.from(secret,'utf8')).update(si,'ascii').digest());
process.stdout.write(si+'.'+sig);
EOF
